import React from "react";
import "./HeroSection.css";
import Arrow from "./assets/Union.svg";
import Car from "./assets/imagecar.svg";
import BGScene from "./assets/BackgroundScenebg.svg"
import {Link} from "react-router-dom";

function HeroSection(){
    return (
        <section className="hero">
            <div className="backgroundcontainer">
                <img className="backgroundimage" src={BGScene} alt="background-image"/>
            </div>
            <h1>Your awesome traffic permit consultant.</h1>
            <Link to="/catalog"> <a className="start-btn" href="#">GET STARTED <img
                src={Arrow} alt="arrow"/></a></Link>
            <div className="car-div">
                <img className="car" src={Car} alt="car"/>
            </div>
        </section>
    );
}

export default HeroSection;
